-- TRANSFORMATION-LOOP-1 (2026-10-06, pillar: autonomy; owner directive 2026-10-06: a continuing program of transformational
-- change, systemwide, fully automatic and 100% autonomous). docs/TRANSFORMATION-PROGRAM.md (TRANSFORMATION-PROGRAM-1) is the
-- audit and the plan; qnfo-fleet-control 0.4.131 is the engine (transformationTick, hourly). This file seeds the engine's
-- registers from the document: one transformation_levers row per lever with its kind (code = a single-file edit the code
-- loop can land; refactor, retire, migration, platform, repo, verify, config; owner = the owner's list, never dispatched),
-- its wave (section 4), its path and anchor where the edit point is known, and the child issue the program's author
-- already filed (adopted, never duplicated). Status seeds: landed where the evidence exists today (named in note),
-- dispatched where a code task is in flight, session where a session-task issue exists, pending otherwise. The loop
-- maintains every row from here on. Also: the merge runner's trusted-origin list gains the program's two origins (backup
-- key kept), the loop's metric and trigger, and a contract on the loop's heartbeat. Idempotent; applied by the session
-- that wrote it. Rollback: DROP TABLE transformation_levers; DROP TABLE transformation_runs; restore ops_config
-- code_merge_trusted_sources from code_merge_trusted_sources--bak-20261006T0730Z; DELETE FROM analytics_metric_triggers
-- WHERE metric_key='transformation_levers_landed_14d'; DELETE FROM metric_registry WHERE metric='transformation_levers_landed_14d';
-- DELETE FROM remediation_contracts WHERE class='transformation-loop-1'.

CREATE TABLE IF NOT EXISTS transformation_levers (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  tp INTEGER NOT NULL,
  n INTEGER NOT NULL,
  key TEXT NOT NULL,
  title TEXT NOT NULL,
  kind TEXT NOT NULL,
  wave TEXT NOT NULL,
  pillar TEXT,
  path TEXT,
  anchor TEXT,
  detail TEXT,
  dod TEXT,
  issue_id INTEGER,
  code_task_id TEXT,
  status TEXT NOT NULL DEFAULT 'pending',
  note TEXT,
  dispatched_at TEXT,
  landed_at TEXT,
  verified_at TEXT,
  stalled_at TEXT,
  updated_at TEXT,
  UNIQUE(tp, n)
);
CREATE TABLE IF NOT EXISTS transformation_runs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ts TEXT,
  worker_version TEXT,
  wave TEXT,
  levers_json TEXT,
  scoreboard_json TEXT,
  actions_json TEXT
);

