INSERT OR IGNORE INTO transformation_levers (tp, n, key, title, kind, wave, pillar, path, anchor, detail, dod, issue_id, status, note, dispatched_at, landed_at) VALUES
 (1, 1, 'trusted-origin-parity', 'The merge runner trusts every origin the planner trusts', 'code', 'W0', 'autonomy', 'qnfo-fleet-control/worker.js', 'function cmTrusted(source, title, list) {', 'cmTrusted accepts the same (source, title-prefix) pairs the code orchestrator planner accepts (METRIC-TRIGGER-, REACH-IDEA-, TP-), read from one shared list.', 'no code_tasks row ends failed with last_error like merge-runner:%not a trusted origin% for a planner-created issue over 14 days', 2005, 'dispatched', 'adopted: issue 2005 carries the code-task line; code task ct_u4ih8uzgsfxzvm branch_pushed 2026-10-06T07:00Z, merge_state rejected by a session review at 07:12Z (the patch trusted qnfo-code-orchestrator pairs; the issues come from qnfo-fleet-control). The first tick flips this lever to session (T1 lever 12) and files CODE-TASK-NEEDS-SESSION-1: a control-plane edit a session merges until T1.8', '2026-10-06T06:00:00Z', NULL),
 (1, 2, 'pr-open-on-20min-tick', 'fleet-control opens PRs for branch_pushed code tasks on the */20 tick (replaces: orchestrator pushes its own branch)', 'code', 'W0', 'autonomy', 'qnfo-fleet-control/worker.js', NULL, 'code-task-publish pushes the branch within a minute; the PR was opened only by the hourly merge tick (40-50 min, 5 h overnight). The */20 branch also runs codeMergeTick(env, { openOnly: true }).', 'median minutes from ready_to_publish to pr_opened_at under 15 over 14 days', 2017, 'landed', 'PR 667 merged 2026-10-06T06:51Z (4ed2900): qnfo-fleet-control 0.4.130 PR-OPEN-ON-20MIN-TICK-1, live at 07:05Z (/health 0.4.130-pr-open-20min); issue 2017 closes on its own probe', '2026-10-06T06:41:00Z', '2026-10-06T06:51:04Z'),
 (1, 3, 'rebase-before-publish', 'Rebase-before-publish: re-anchor against current main before the push and retry once on stale base or patch does not apply', 'code', 'W0', 'autonomy', 'qnfo-code-orchestrator/worker.js', NULL, 'Seven closures named stale base or patch does not apply.', 'no code_tasks row ends with last_error naming stale base or does not apply over 14 days', NULL, 'pending', NULL, NULL, NULL),
 (1, 4, 'anchor-repair', 'An anchor that occurs 0 or 2 times is repaired by the model, not parked as needs_human', 'code', 'W0', 'autonomy', 'qnfo-code-orchestrator/worker.js', NULL, 'Ask the model once for a replacement anchor from the current file; park only after the repaired anchor also fails.', 'code_tasks rows with last_error like %anchor% ending needs_human = 0 over 14 days', 2007, 'session', 'adopted: issue 2007 (session-task after the code loop paraphrased a string literal instead)', '2026-10-06T06:41:00Z', NULL),
 (1, 5, 'container-verifier', 'Every code task runs the worker suites and the deploy gate in the PyContainer before a PR', 'code', 'W0', 'autonomy', 'qnfo-code-orchestrator/worker.js', NULL, 'node --check, the changed worker''s *.test.mjs and scripts/deploy_gate.py --check inside the container; a failure is one more propose round, not a PR.', '0 code-loop PRs fail the gate over 14 days and no task ends no-verifier', 2008, 'session', 'adopted: issue 2008 (session-task)', '2026-10-06T06:27:00Z', NULL),
 (1, 6, 'merges-per-tick-3', 'code_merge_max_merges_per_tick reads 3 in ops_config', 'config', 'W0', 'autonomy', NULL, NULL, 'Raise to 5 only when the queue holds green PRs at tick time.', 'ops_config code_merge_max_merges_per_tick = 3', NULL, 'landed', 'ops_config code_merge_max_merges_per_tick = 3 read live 2026-10-06T07:05Z', NULL, '2026-10-06T07:05:00Z'),
 (1, 7, 'evolve-parse-gate', 'A candidate that does not parse is re-asked once with the parse error; evolve_parse_pass_pct_7d is graded', 'code', 'W0', 'autonomy', 'qnfo-fleet-control/worker.js', NULL, '93 of 120 evolve candidates were rejected-parse.', 'evolve_parse_pass_pct_7d registered and >= 50', NULL, 'pending', NULL, NULL, NULL),
 (1, 8, 'branch-protection-control-plane', 'GitHub branch protection on main with the required checks, then drop CONTROL-PLANE-MANUAL-1 and shrink CM_DENY for fully green heads', 'platform', 'W1', 'autonomy', 'qnfo-fleet-control/worker.js', NULL, 'The platform, not the policy, becomes the gate; control-plane changes keep the stricter test set (T5.4). The loop treats every control-plane code lever as a session lever until this lands.', 'main protected with gate, guard, mirror-guard, comparator, charter and test required; at least 10 control-plane PRs merged by the loop', NULL, 'pending', NULL, NULL, NULL),
 (1, 9, 'code-task-lines-on-triggers', 'Every enabled trigger whose lever is a single-file change carries code-task and code-anchor lines (ACT-BRIDGE-1)', 'migration', 'W0', 'autonomy', 'migrations', NULL, 'The 69 triggers without a line are reviewed in analytics_metric_triggers.action by one migration.', 'breach_code_task_pct >= 30', NULL, 'pending', NULL, NULL, NULL),
 (1, 10, 'orphan-suites-into-gate', 'The 19 suites no workflow references join the gate through one suite runner', 'repo', 'W1', 'autonomy', '.github/workflows/deploy-gate.yml', NULL, 'scripts/run-suites.mjs runs every *.test.mjs of the changed workers (T3.8).', 'every *.test.mjs in the repo is run by a workflow on every PR', NULL, 'pending', NULL, NULL, NULL),
 (1, 11, 'multi-file-tasks', 'Multi-file code tasks: the task carries a file list and the agent edits a branch checkout in the container', 'refactor', 'W3', 'autonomy', 'qnfo-code-orchestrator/worker.js', NULL, 'The more-than-one-file refusal becomes more-than-the-task''s-file-list.', 'a code task with two files reaches a merged PR', NULL, 'pending', NULL, NULL, NULL),
 (1, 12, 'session-fallback', 'A task that fails twice files CODE-TASK-NEEDS-SESSION-1 with the failure text; the watchmaker index counts those rows', 'code', 'W0', 'autonomy', 'qnfo-fleet-control/worker.js', NULL, 'TRANSFORMATION-LOOP-1 (qnfo-fleet-control 0.4.131) files the row when a dispatched lever''s code tasks all ended failed, needs_human or closed; qnfo-fleet-dashboard WATCHMAKER_OPS transformation-loop counts the open rows.', 'an open CODE-TASK-NEEDS-SESSION-1 row raises watchmaker_index; none open means no session dependence', NULL, 'pending', 'in PR 662 (session_01CX4ooVZuEie1F9eEtYHx2u); lands when qnfo-fleet-control 0.4.131 is live', NULL, NULL),
 (1, 13, 'noop-proposal-gate', 'The code orchestrator refuses a proposal that changes only string literals or comments and runs one more propose round', 'code', 'W0', 'autonomy', 'qnfo-code-orchestrator/worker.js', NULL, 'Two TP-1 tasks returned a 2-line paraphrase of a string literal plus the VERSION bump and passed the verifier.', 'no merged code-loop PR whose non-VERSION diff touches only string literals or comments over 14 days', 2018, 'landed', 'PR 666 merged 2026-10-06T06:42Z (4b03a30): qnfo-code-orchestrator 0.3.17 NOOP-PROPOSAL-GATE-1, live (/health 0.3.17-noop-gate); issue 2018 closes on its own probe', '2026-10-06T06:41:00Z', '2026-10-06T06:42:49Z');

