 (9, 2, 'prune-accepts-10143', 'The deploy prune accepts error 10143 as well as 10144 (DANGLING-BINDING-PRUNE-1)', 'code', 'W0', 'core', 'qnfo-ops/worker.js', NULL, NULL, 'a dangling binding refused with 10143 is pruned by the canonical deploy', NULL, 'landed', 'qnfo-ops 2.38.43-dangling-10143 deployed 2026-10-06 (cf-ops-actions run 37423700798); 2.38.44-indexer-fold live at 07:05Z', NULL, '2026-10-06T06:27:00Z'),
 (9, 3, 'deployer-fallback', 'canonical-deploy.yml runs the code-only bootstrap once when /ops/deploy fails for qnfo-ops itself and records which path landed in fleet_deploys', 'repo', 'W1', 'core', '.github/workflows/canonical-deploy.yml', NULL, 'qnfo-ops deploys itself through its own live code; on 2026-10-06 its fix could not ship until the bindings were removed out of band. deploy-qnfo-ops.yml and scripts/raw_put.py exist but no loop takes them.', 'a forced /ops/deploy failure for qnfo-ops lands through the bootstrap path with a fleet_deploys row naming the path', NULL, 'pending', NULL, NULL, NULL),
