-- Issue 1677 is closed although its lever has not landed: the loop would land it on the closed issue. Decouple so the lever
-- is re-verified by probe (T8.3's suite), not assumed.
UPDATE transformation_levers SET issue_id = NULL WHERE tp = 8 AND n = 2;

-- The merge runner's trusted-origin list gains the program's two origins: the engine files TP-* issues as qnfo-fleet-control,
-- the program's author filed the epics as TRANSFORMATION-PROGRAM-1. Same trust as METRIC-TRIGGER- and REACH-IDEA- (kernel
-- loops). Backup of the previous value kept under its own key.
INSERT OR IGNORE INTO ops_config (key, value, note) SELECT 'code_merge_trusted_sources--bak-20261006T0730Z', value, 'backup before TRANSFORMATION-LOOP-1 appended qnfo-fleet-control|TP- and TRANSFORMATION-PROGRAM-1|TP-' FROM ops_config WHERE key = 'code_merge_trusted_sources';
UPDATE ops_config SET value = value || ',qnfo-fleet-control|TP-,TRANSFORMATION-PROGRAM-1|TP-', updated_at = datetime('now') WHERE key = 'code_merge_trusted_sources' AND value NOT LIKE '%qnfo-fleet-control|TP-%';

INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, baseline, target, owner, disposition_actor, refresh_cadence, warning_band, kill_band, state, refresh_class)
VALUES ('transformation_levers_landed_14d', 'system', 'leading',
  'COUNT(transformation_levers WHERE landed_at or verified_at in the last 14 days): levers of docs/TRANSFORMATION-PROGRAM.md that reached main or closed with evidence (qnfo-fleet-control TRANSFORMATION-LOOP-1, hourly)',
  'qnfo-audit.transformation_levers (GET https://qnfo-fleet-control.q08.workers.dev/transformation)',
  '0 (2026-10-06, before the loop)', '>= 2 every 14 days while any wave is open (the program moves); rising',
  'qnfo-fleet-control', 'trigger lt 1 -> METRIC-TRIGGER issue (migrations/2026-10-06-transformation-loop.sql)', 'hourly', '< 2', '< 1', 'MEASURED', 'computed');

-- First value from the seed, so the trigger below judges a number and not NULL before the loop's first tick.
UPDATE metric_registry SET last_value = (SELECT COUNT(*) FROM transformation_levers WHERE COALESCE(verified_at, landed_at) >= strftime('%Y-%m-%dT%H:%M:%SZ', 'now', '-14 days')), last_refreshed = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE metric = 'transformation_levers_landed_14d' AND last_value IS NULL;

INSERT OR IGNORE INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT 'transformation_levers_landed_14d', 'Autonomy gap: no transformation lever landed in 14 days (the program is not moving)', 'registry', 'lt', 1, 7,
  'Pillar autonomy (TRANSFORMATION-LOOP-1, owner directive 2026-10-06: a continuing, fully autonomous program of transformational change). No lever of docs/TRANSFORMATION-PROGRAM.md reached main or closed with evidence in 14 days. Read GET https://qnfo-fleet-control.q08.workers.dev/transformation: (1) last_run older than 2h means the hourly tick is not running (qnfo-fleet-control /health, cloud_ops_events transformation-tick-<day>); (2) levers stuck in dispatched: the code loop refused or parked them (code_tasks last_error; CODE-TASK-NEEDS-SESSION-1 rows name the ones that need a session); (3) levers stuck in session: the open TP-* session-task issues are the queue, take the oldest in wave order; (4) nothing pending in the active wave: the wave''s exit metrics name what is missing. Never raise a cap, never add a model call while a fleet_budget cap is breached, never weaken a guard to make a lever land. Definition of done: metric_registry.transformation_levers_landed_14d >= 1; record before and after in issue_triage.close_evidence.',
  'qnfo-fleet-control', 'agent_issues', 24, 1, 'TRANSFORMATION-LOOP-1 (migrations/2026-10-06-transformation-loop.sql)'
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers x WHERE x.metric_key = 'transformation_levers_landed_14d');

-- Closing probe for the loop itself: a run in the last 2 hours. Pending until the first run.
INSERT INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status)
VALUES ('transformation-loop-1', NULL,
  'qnfo-fleet-control 0.4.131+ deployed; transformation_levers seeded',
  'observe only: the hourly tick writes transformation_runs and cloud_ops_events transformation-tick-<day>',
  'SELECT ''ok'' AS expected, CASE WHEN (SELECT MAX(ts) FROM transformation_runs) IS NULL THEN ''pending: loop has not run'' WHEN (SELECT MAX(ts) FROM transformation_runs) < strftime(''%Y-%m-%dT%H:%M:%SZ'',''now'',''-2 hours'') THEN ''stale: last run older than 2h'' ELSE ''ok'' END AS observed',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active')
ON CONFLICT(class) DO UPDATE SET precondition=excluded.precondition, action=excluded.action, verify_probe=excluded.verify_probe, status='active';
